theme.css:
/* theme: Golden Tension | A day when political gold surges and oil burns at the Strait, with markets caught between red and green. */
/* mood: tense */
/* layout: hero=centered; political-news=outline/grid-2; financial-news=stat/feature; entertainment-news=tile/masonry; sports=numbered/grid-3; music-releases=plain/stack; stock-analysis=banner/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #fbf3e0;
  --paper-alt: #f5e8cc;
  --ink: #1a150c;
  --ink-soft: #4a3f2d;
  --muted: #6d5f47;
  --accent: #a94d0a;
  --accent-ink: #fffaf0;
  --rule: #e0d3b8;
  --font-display: var(--ff-syne), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

/* Hero: centered, with a gold-on-amber gradient band */
.diary-page[data-hero="centered"] .diary-hero {
  background:
    linear-gradient(135deg, var(--paper-alt) 0%, var(--paper) 45%, #f7eccf 100%);
  border-bottom: 3px solid var(--accent);
}

.diary-page[data-hero="centered"] .diary-hero-inner {
  position: relative;
  padding-block: 4rem 4.5rem;
}

.diary-page[data-hero="centered"] .diary-kicker {
  font-size: 0.85rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page[data-hero="centered"] .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--ink);
  text-shadow: 0 2px 0 rgba(169, 77, 10, 0.12);
}

.diary-page[data-hero="centered"] .diary-summary {
  font-size: clamp(1.2rem, 2.4vw, 1.55rem);
  font-style: italic;
  color: var(--ink-soft);
}

.diary-page[data-hero="centered"] .diary-theme-note {
  font-size: 0.9rem;
  letter-spacing: 0.04em;
}

.diary-page[data-hero="centered"] .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  box-shadow: 0 3px 0 rgba(169, 77, 10, 0.25);
}

/* Contents: amber-tinted active state */
.diary-page .diary-toc-link.is-active {
  color: var(--accent);
  font-weight: 600;
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

/* Section headers with oversized numerals */
.diary-page .diary-section-head {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.75rem;
  margin-bottom: 2.25rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 0.8;
  color: var(--accent);
  letter-spacing: -0.02em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

/* Political: outlined cards with a diagonal accent notch */
.diary-page [data-section="political-news"] .diary-card--outline .diary-card-inner {
  position: relative;
  padding: 1.75rem 1.75rem 1.75rem 2.25rem;
  border: 2px solid var(--rule);
  border-radius: 0;
  background:
    linear-gradient(135deg, transparent 0%, transparent 85%, rgba(169, 77, 10, 0.06) 100%);
}

.diary-page [data-section="political-news"] .diary-card--outline .diary-card-inner::before {
  content: "";
  position: absolute;
  left: -2px;
  top: -2px;
  width: 0.9rem;
  height: 0.9rem;
  background: var(--accent);
  clip-path: polygon(0 0, 100% 0, 0 100%);
}

.diary-page [data-section="political-news"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.7rem;
  font-weight: 600;
  color: var(--ink);
}

/* Financial: stat cards with a gold coin-like figure */
.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  padding-top: 1.25rem;
  border-top: 4px solid var(--accent);
  background: linear-gradient(180deg, rgba(169, 77, 10, 0.05) 0%, transparent 45%);
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(3rem, 10cqi, 4.5rem);
  font-weight: 700;
  color: var(--accent);
  position: relative;
  display: inline-block;
}

.diary-page [data-section="financial-news"] .diary-card-figure::after {
  content: "▲";
  font-size: 0.5em;
  vertical-align: top;
  margin-left: 0.15em;
  color: var(--accent);
}

/* Entertainment: tile cards with a warm shadow */
.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  padding: 1.75rem;
  border-left: 4px solid var(--accent);
  box-shadow: 0 8px 0 -4px rgba(169, 77, 10, 0.15);
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 0.01em;
}

/* Sports: numbered cards on a dark-to-light amber scale */
.diary-page [data-section="sports"] .diary-card--numbered .diary-card-inner {
  padding: 1.5rem;
  background: linear-gradient(135deg, rgba(169, 77, 10, 0.04) 0%, transparent 60%);
  border-bottom: 1px solid var(--rule);
}

.diary-page [data-section="sports"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.5rem;
  font-weight: 700;
  color: var(--accent);
}

/* Music: plain with spotify spacing, keeping it airy */
.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-inner {
  gap: 0.35rem;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 0.02em;
  font-size: 1.5rem;
}

.diary-page [data-section="music-releases"] .diary-card-body {
  color: var(--ink-soft);
}

/* Stock analysis: banner cards in a market-tape motif */
.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-inner {
  border: 2px solid var(--rule);
  border-radius: 0.25rem;
  overflow: hidden;
  background: var(--paper);
}

.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  padding: 0.9rem 1.25rem;
}

.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-body {
  padding: 1.25rem 1.25rem 1.5rem;
}

/* Outlook: timeline cards with amber dots */
.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper), 0 0 0 7px rgba(169, 77, 10, 0.2);
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::before {
  background: linear-gradient(180deg, var(--accent) 0%, var(--rule) 100%);
  width: 3px;
  left: 0.25rem;
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-size: 1.5rem;
  font-family: var(--font-display);
  font-weight: 600;
}

/* Card typography refinements */
.diary-page .diary-card--outline .diary-card-body,
.diary-page .diary-card--banner .diary-card-body,
.diary-page .diary-card--tile .diary-card-body {
  font-size: 1.02rem;
  line-height: 1.65;
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  background: transparent;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Prose citations in amber */
.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: rgba(169, 77, 10, 0.4);
  font-weight: 700;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

/* Markets sparklines: amber-up, deep-red-down */
.diary-page .diary-spark {
  border: 1px solid var(--rule);
  background: var(--paper-alt);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: #8f2d0c;
}

.diary-page .diary-markets-label {
  color: var(--muted);
}

/* Footer warm treatment */
.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
  background: linear-gradient(0deg, var(--paper-alt) 0%, var(--paper) 100%);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Subtle entrance for the hero summary only */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-summary {
    animation: diary-fade-in 500ms ease-out both;
  }
}

@keyframes diary-fade-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}
